use genex::prelude::*;

// genex.toml: a loose image the code samples gets a row, so the import ships it compressed:
// [[texture]]
// path = "cc0/plaster/color.jpg"
// usage = "color"

/// What a facet exists to build samples real maps; its stand-in colour shows only until they load.
fn crate_material() -> Material {
    Material::color(Color::WHITE)
        .with_base_texture("cc0/wood-crate/color.jpg")
        .with_normal_texture("cc0/wood-crate/normal.jpg", 1.0)
        .with_metal_rough_texture("cc0/wood-crate/rough.jpg")
        .with_untextured_color(Color::rgb(120, 92, 60))
}
